int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    int ret;
    struct usb_device *udev = interface_to_usbdev(intf);
    struct usb_host_endpoint *ep_in, *ep_out;
    struct urb *urb;
    void *buf;
    struct powermate_dev *dev;

    ep_in = usb_find_int_in_endpoint(intf->cur_altsetting);
    if (!ep_in) {
        dev_err(&intf->dev, "No interrupt in endpoint found\n");
        return -ENODEV;
    }

    ep_out = usb_find_int_out_endpoint(intf->cur_altsetting);
    if (!ep_out) {
        dev_err(&intf->dev, "No interrupt out endpoint found\n");
        return -ENODEV;
    }

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!urb) {
        ret = -ENOMEM;
        goto err_free_dev;
    }

    buf = kmalloc(USB_PACKET_SIZE, GFP_KERNEL);
    if (!buf) {
        ret = -ENOMEM;
        goto err_free_urb;
    }

    usb_fill_int_urb(urb, udev, usb_rcvintpipe(udev, ep_in->desc.bEndpointAddress),
                     buf, USB_PACKET_SIZE, powermate_interrupt, dev,
                     ep_in->desc.bInterval);

    ret = input_register_device(&dev->input_dev);
    if (ret) {
        dev_err(&intf->dev, "Failed to register input device\n");
        goto err_free_buf;
    }

    switch (le16_to_cpu(udev->descriptor.idProduct)) {
        case USB_DEVICE_ID_LOGITECH_POWERMATE:
            dev->input_dev.name = "Logitech PowerMate";
            break;
        case USB_DEVICE_ID_LOGITECH_POWERMATE2:
            dev->input_dev.name = "Logitech PowerMate 2";
            break;
        default:
            dev->input_dev.name = "Unknown PowerMate";
            break;
    }

    dev->led_pulse = 0;
    dev->pulse_period = 100;

    dev_set_drvdata(&intf->dev, dev);
    usb_set_intfdata(intf, dev);

    ret = usb_submit_urb(urb, GFP_KERNEL);
    if (ret < 0) {
        dev_err(&intf->dev, "Failed to submit URB: %d\n", ret);
        goto err_unregister_input;
    }

    return 0;

err_unregister_input:
    input_unregister_device(&dev->input_dev);
err_free_buf:
    kfree(buf);
err_free_urb:
    usb_free_urb(urb);
err_free_dev:
    kfree(dev);
    return ret;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct powermate_dev *dev;
    int i, error = -ENOMEM;

    iface_desc = intf->cur_altsetting;
    if (iface_desc->desc.bNumEndpoints != 1)
        return -ENODEV;

    endpoint = &iface_desc->endpoint[0].desc;
    if (!usb_endpoint_is_int_in(endpoint))
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(interface_to_usbdev(intf));
    dev->interface = intf;

    usb_fill_int_urb(dev->urb, dev->udev, usb_rcvintpipe(dev->udev, endpoint->bEndpointAddress),
                     dev->data, sizeof(dev->data), powermate_irq, dev, endpoint->bInterval);

    dev->input_dev = input_allocate_device();
    if (!dev->input_dev)
        goto free_dev;

    dev->input_dev->name = "Logitech PowerMate";
    dev->input_dev->id.bustype = BUS_USB;
    dev->input_dev->id.vendor = le16_to_cpu(dev->udev->descriptor.idVendor);
    dev->input_dev->id.product = le16_to_cpu(dev->udev->descriptor.idProduct);
    dev->input_dev->id.version = 0x0100;

    __set_bit(EV_REL, dev->input_dev->evbit);
    __set_bit(EV_KEY, dev->input_dev->evbit);
    __set_bit(BTN_MISC, dev->input_dev->keybit);
    __set_bit(KEY_CONTINUOUS, dev->input_dev->keybit);
    __set_bit(REL_WHEEL, dev->input_dev->relbit);

    error = input_register_device(dev->input_dev);
    if (error)
        goto free_input_dev;

    usb_set_intfdata(intf, dev);

    dev->led_pulses = 0;
    dev->led_state = 0;

    return 0;

free_input_dev:
    input_free_device(dev->input_dev);
free_dev:
    kfree(dev);
    return error;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct powermate_dev *dev;
    int retval = -ENOMEM;

    iface_desc = &intf->cur_altsetting[0];
    if (iface_desc->desc.bNumEndpoints != 1)
        return -ENODEV;

    endpoint = &iface_desc->endpoint[0].desc;
    if (!usb_endpoint_is_int_in(endpoint))
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(interface_to_usbdev(intf));
    dev->intf = intf;

    usb_fill_int_urb(&dev->urb, dev->udev, usb_rcvintpipe(dev->udev, endpoint->bEndpointAddress),
                     dev->data, USB_PACKET_SIZE, powermate_irq, dev, endpoint->bInterval);

    dev->urb->transfer_dma = dev->data_dma;
    dev->urb->transfer_flags |= URB_NO_TRANSFER_DMA_MAP;

    dev->input_dev = input_allocate_device();
    if (!dev->input_dev)
        goto err_free_dev;

    set_bit(EV_REL, dev->input_dev->evbit);
    set_bit(EV_KEY, dev->input_dev->evbit);
    set_bit(BTN_MISC, dev->input_dev->keybit);

    dev->input_dev->name = "Logitech PowerMate";
    dev->input_dev->id.bustype = BUS_USB;
    dev->input_dev->id.vendor = le16_to_cpu(dev->udev->descriptor.idVendor);
    dev->input_dev->id.product = le16_to_cpu(dev->udev->descriptor.idProduct);
    dev->input_dev->id.version = 0x0100;

    dev->input_dev->private = dev;

    dev->pulse_width = DEFAULT_PULSE_WIDTH;
    dev->pulse_period = DEFAULT_PULSE_PERIOD;
    dev->brightness = DEFAULT_BRIGHTNESS;

    usb_set_intfdata(intf, dev);

    retval = input_register_device(dev->input_dev);
    if (retval)
        goto err_free_input_dev;

    return 0;

err_free_input_dev:
    input_free_device(dev->input_dev);
err_free_dev:
    kfree(dev);
    return retval;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct powermate_dev *pdev;
    int retval = -ENOMEM;

    iface_desc = &intf->cur_altsetting[0];
    endpoint = &iface_desc->endpoint[0].desc;

    pdev = kzalloc(sizeof(*pdev), GFP_KERNEL);
    if (!pdev)
        goto error;

    pdev->dev = usb_get_dev(usb_ifnum_to_index(intf->usbdev, intf->altsetting[0].desc.bInterfaceNumber));
    pdev->intf = intf;

    usb_set_intfdata(intf, pdev);

    pdev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!pdev->urb)
        goto error_free_dev;

    pdev->data = kmalloc(PM_PACKET_SIZE, GFP_KERNEL);
    if (!pdev->data)
        goto error_free_urb;

    usb_fill_int_urb(pdev->urb, pdev->dev,
                     usb_rcvintpipe(pdev->dev, endpoint->bEndpointAddress),
                     pdev->data, PM_PACKET_SIZE,
                     powermate_irq, pdev, endpoint->bInterval);

    pdev->input_dev = input_allocate_device();
    if (!pdev->input_dev)
        goto error_free_data;

    pdev->input_dev->evbit[0] = BIT_MASK(EV_REL) | BIT_MASK(EV_KEY);
    pdev->input_dev->keybit[BIT_WORD(BTN_0)] = BIT_MASK(BTN_0);
    pdev->input_dev->relbit[0] = BIT_MASK(REL_X);

    snprintf(pdev->input_dev->name, sizeof(pdev->input_dev->name), "PowerMate");

    input_register_device(pdev->input_dev);
    usb_fill_int_urb(pdev->urb, pdev->dev,
                     usb_rcvintpipe(pdev->dev, endpoint->bEndpointAddress),
                     pdev->data, PM_PACKET_SIZE,
                     powermate_irq, pdev, endpoint->bInterval);
    usb_submit_urb(pdev->urb, GFP_KERNEL);

    return 0;

error_free_data:
    kfree(pdev->data);
error_free_urb:
    usb_free_urb(pdev->urb);
error_free_dev:
    kfree(pdev);
error:
    return retval;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct usb_host_interface *host_intf;
    struct usb_endpoint_descriptor *ep_desc;
    struct powermate_dev *dev;
    int ret;

    host_intf = &intf->cur_altsetting[0];
    ep_desc = &host_intf->endpoint[0].desc;

    if (!usb_endpoint_is_int_in(ep_desc)) {
        return -ENODEV;
    }

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev) {
        return -ENOMEM;
    }

    dev->usbdev = usb_get_dev(interface_to_usbdev(intf));
    dev->intf = intf;

    dev->input = input_allocate_device();
    if (!dev->input) {
        ret = -ENOMEM;
        goto err_free_dev;
    }

    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb) {
        ret = -ENOMEM;
        goto err_free_input;
    }

    usb_fill_int_urb(dev->urb, dev->usbdev,
                     usb_rcvintpipe(dev->usbdev, ep_desc->bEndpointAddress),
                     dev->data, sizeof(dev->data), powermate_irq, dev,
                     ep_desc->bInterval);

    dev->urb->transfer_flags |= URB_NO_TRANSFER_FLAG;

    input_set_drvdata(dev->input, dev);
    dev->input->name = "Logitech PowerMate";
    dev->input->id.bustype = BUS_USB;
    dev->input->id.vendor = le16_to_cpu(dev->usbdev->descriptor.idVendor);
    dev->input->id.product = le16_to_cpu(dev->usbdev->descriptor.idProduct);
    dev->input->id.version = 0x0100;

    input_set_capability(dev->input, EV_REL, REL_DIAL);
    input_set_capability(dev->input, EV_LED, LED_MISC);

    ret = input_register_device(dev->input);
    if (ret) {
        goto err_free_urb;
    }

    dev->pulse_brightness = 0;
    dev->pulse_period = 0;

    usb_set_intfdata(intf, dev);

    return 0;

err_free_urb:
    usb_free_urb(dev->urb);
err_free_input:
    input_free_device(dev->input);
err_free_dev:
    kfree(dev);
    return ret;
}
